import{_ as i,l as o,o as e,c as n,v as r,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"生成式奖励模型","description":"","frontmatter":{"title":"生成式奖励模型","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/generative-rm.md","filePath":"llm/generative-rm.md","lastUpdated":1789023840000}'),m={name:"llm/generative-rm.md"};function _(E,a,c,A,P,f){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="生成式奖励模型" tabindex="-1">生成式奖励模型 <a class="header-anchor" href="#生成式奖励模型" aria-label="Permalink to &quot;生成式奖励模型&quot;">​</a></h1><div class="epigraph"><p>不要只吐一个标量；让裁判先写出谁更好、为什么，再把那份判断收成奖励。</p><footer>—— Zhang 等 Generative Verifiers；Mahan 等 Generative Reward Models</footer></div><p><a href="/llm/rm-overoptimization">上一课</a>把标量 RM 的命运写成过优化曲线：点估计的 \\(r_\\phi\\) 一旦成为目标就会被榨干。缺口是：<strong>判别头把全部偏好压进一个 logit，既难解释，也给捷径留了短特征。</strong> 生成式奖励模型（GenRM）改用自回归：对 \\((x,y)\\) 或成对 \\((y_a,y_b)\\) 生成评语，再解析出分或胜负。本课写这条对象转换。后课 LLM 裁判谈提示与偏差；本课先把「奖励是一段话」接上 <a href="/llm/rlhf-pipeline">RLHF</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标量 RM 的最后一层是线性头，长度、列表、关键词极易占满。人类比较时其实先有理由再给序；BT 训练把理由扔掉了。GenRM 要恢复中间文本：给定题目与回答，生成「逐步是否合法 / 哪条更好」，用生成概率或解析出的标签当 \\(r\\)。希望是：黑客必须同时骗过一段连贯评语，而不只是抬高一个 logit。</p><p>这不是 <a href="/llm/process-supervision">过程监督</a> 的 PRM。PRM 预测逐步对错的分类头；GenRM 可以是验证者风格的 CoT，也可以是成对比较的解说。两者都比标量厚，也都引入新的过优化面：策略可以学着写「裁判爱看的回答」，或直接污染评语格式。</p><h3 id="生成的是验证-还是比较" tabindex="-1">生成的是验证，还是比较 <a class="header-anchor" href="#生成的是验证-还是比较" aria-label="Permalink to &quot;生成的是验证，还是比较&quot;">​</a></h3><p>验证式：输入 \\((x,y)\\)，生成对错或分数。比较式：输入 \\((x,y_a,y_b)\\)，生成胜者。前者可直接给 PPO；后者更像标注员，要先采样候选再判。Zhang 等人的生成式验证器主要走前者，把正确性写成下一个 token 的似然。Mahan 等人强调生成式偏好模型在分布外更稳。不要把两篇收成同一个头。</p><p><span class="marginnote">用 \\(\\log p(\\text{Yes}\\mid x,y)\\) 当奖励，仍是标量，只是这个标量经过了一段 CoT。CoT 被优化之后，一样会 Goodhart。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练数据：带评语的比较，或带逐步对错的解答（PRM800K 一类也可拿来训生成验证器）。损失是评语 token 的因果 LM，外加对最终标签 token 的加权。推理：采样或贪婪生成评语，解析最后一行的分数 / 胜负；或对「Yes/No」算对数概率，避免采样噪声。接到 PPO 时，\\(r\\) 仍是标量，只是计算贵一个生成器。</p>',11)),(e(),s(h,null,{default:t(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20XY%5B%22(x%2C%20y)%20%E6%88%96%E6%88%90%E5%AF%B9%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E8%AF%84%E8%AF%AD%22%5D%0A%20%20GEN%20--%3E%20PAR%5B%22%E8%A7%A3%E6%9E%90%E6%A0%87%E7%AD%BE%20%2F%20Yes%20%E4%BC%BC%E7%84%B6%22%5D%0A%20%20PAR%20--%3E%20R%5B%22%E6%A0%87%E9%87%8F%20r%22%5D%0A%20%20R%20--%3E%20PPO%5B%22PPO%20%2F%20BoN%22%5D%0A%20%20GEN%20--%3E%20HACK%5B%22%E8%AF%84%E8%AF%AD%E6%9C%AC%E8%BA%AB%E5%8F%AF%E8%A2%AB%E4%BC%98%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 <a href="/llm/dpo">DPO</a> 的差别：DPO 不训奖励；GenRM 仍训奖励，只是奖励器是 LM。可以先 GenRM 打分再 DPO，那是用生成器当教师，不是 GenRM 本身做策略优化。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>评语提供的归纳偏置是：判断必须经过可写下来的理由。对数学，这接近生成式过程验证；对开放偏好，理由可能只是漂亮话，不增加信息。经验上，生成式验证器在可核对域（对错有金标）提升更明显，因为评语的中间步骤能被结果部分约束。开放域里，生成式 RM 的胜率校准仍要单独做，上一课的仿射对「Yes 概率」同样适用。</p><p>过优化通道从「抬 logit」变成「写裁判爱看的表面」。若裁判总夸列表，策略仍写列表，只是现在还配一段自我表扬。集成 GenRM（多份评语）能推迟，成本是 \\(K\\) 次长生成。</p><p><span class="marginnote">评语长度要截断并格式化。无约束 CoT 会让延迟不可控，RL 墙钟被裁判吃掉。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>GenRM 的墙钟常是标量 RM 的数十倍。在线 PPO 每条轨迹都跑生成裁判，只适合小规模或离线打分。可验证域应优先 <a href="/llm/verifiable-reward">程序校验</a>，不要用生成器代替编译器。下一课把「用现成 LLM + 提示当裁判」从「专门训一个生成式 RM」里拆出来：前者更常见，偏差也更文献化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GenRM 用自回归评语再解析成 \\(r\\)，加厚奖励器，不取消标量过优化。</li><li>验证式与比较式是两种输入；不要混成一个头。</li><li>可核对域更受惠；开放域的评语可能只是修辞。</li><li>在线 RL 成本高，优先离线打分或可验证奖励。</li><li>出处：Zhang 等 Generative Verifiers；Mahan 等 Generative Reward Models；过优化仍见 Gao 等。</li></ul>',9))])}const u=i(m,[["render",_]]);export{M as __pageData,u as default};
